// ❌ OLD: Date methods MUTATE the instance. To keep the original you
// must remember to copy first; DST and month boundaries are easy to
// get wrong (setDate+1 in DST-spring can land on the wrong hour).
const d = new Date('2026-03-07T12:00:00Z');
const start = d; // ❌ OLD: this is the SAME object

d.setDate(d.getDate() + 1); // ❌ OLD: mutates `d` AND `start` in place

// `start` now points to the mutated date — the original is gone.
console.log(d.toISOString());
console.log(start === d); // true — both are the mutated instance

// Timezone math (adding 24h across a DST shift) also changes the wall
// clock unexpectedly because setDate works on the local civil date.

// ✅ NEW: Temporal values are immutable — every operation returns a new
// instance, so the original is always preserved. Calendar arithmetic is
// timezone- and calendar-aware by default.
const t = Temporal.Now.zonedDateTimeISO(); // ✅ NEW: immutable snapshot
const tomorrow = t.add({ days: 1 }); // ✅ NEW: new ZonedDateTime, t untouched

console.log(t.toString()); // original unchanged
console.log(tomorrow.toString()); // exactly one civil day later

// DST-safe: adding { days: 1 } preserves the wall-clock time across a
// spring-forward/fall-back transition, unlike setDate + 24h.
